import { Component } from '@angular/core';

@Component({
  selector: 'app-header',
  templateUrl: './header.component.html',
  styleUrls: ['./header.component.css']
})
export class HeaderComponent {
  isMobileMenuOpen: boolean = false;

  toggleMobileMenu(): void {
    this.isMobileMenuOpen = !this.isMobileMenuOpen;
  }

  closeMobileMenu(): void {
    this.isMobileMenuOpen = false;
  }
}
<header class="app-header-container">
    <!-- TOP BAR - 100% WIDTH ACROSS THE VERY TOP -->
    <div class="top-header-bar">
        <top-header></top-header>
    </div>

    <!-- MAIN BAR - LOGO ON TOP-LEFT, MENU ON TOP-RIGHT -->
    <div class="main-header-bar">
        <div class="app-header-logo" routerLink="/home" (click)="closeMobileMenu()">
            eKart
        </div>

        <div class="desktop-header-menu">
            <main-menu></main-menu>
        </div>

        <!-- MOBILE HAMBURGER TOGGLE BUTTON -->
        <button class="mobile-hamburger-btn" (click)="toggleMobileMenu()" aria-label="Toggle Navigation Menu">
            <i class="fa" [ngClass]="isMobileMenuOpen ? 'fa-times' : 'fa-bars'"></i>
        </button>
    </div>

    <!-- MOBILE DRAWER MENU -->
    <div class="mobile-drawer-menu" [class.open]="isMobileMenuOpen">
        <div (click)="closeMobileMenu()">
            <main-menu></main-menu>
        </div>
    </div>
</header>
